def build_with_cycle(values: list[int], pos: int) -> tuple[ListNode | None, list[ListNode]]:
    """pos = index the tail links back to, or -1 for no cycle."""
    nodes = [ListNode(v) for v in values]
    for a, b in zip(nodes, nodes[1:]):
