def remove_nth_from_end(head: ListNode | None, n: int) -> ListNode | None:
    dummy = ListNode(0, head)
    lead = trail = dummy
    for _ in range(n):
        lead = lead.next                # lead is now n nodes ahead of trail
    while lead.next:
        lead = lead.next
        trail = trail.next
    trail.next = trail.next.next        # trail is just before the node to remove
    return dummy.next

