node = chain
for i in range(1, 5000):
    node.right = TreeNode(i)
    node = node.right
assert max_depth_bfs(chain) == 5000
try:
    max_depth(chain)
    raise AssertionError("expected RecursionError")
except RecursionError:
    pass                                    # the default limit is about 1,000 frames

